/**
 * Billing-period arithmetic: where a period ends, what a full charge comes to, and how much of it a mid-period change owes.
 *
 * Pure functions over `IsoTimestamp`s and `Date`s. The renewal job and the
 * seat and plan changes both call these, so they cannot disagree about a
 * boundary.
 *
 * Must call (do not reimplement): parseIso, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { parseIso } from "@/lib/date";
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export interface BillingPeriod {
  readonly start: IsoTimestamp;
  readonly end: IsoTimestamp;
}

/** Calendar months one billing interval spans. */
export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * The end of a period that starts at `start` and runs for one interval. The
 * end keeps the start's day and time; where the target month is shorter, it
 * falls on that month's last day. Because each period is measured from the
 * previous end, a clamped day carries forward (28 Feb → 28 Mar).
 */
export function periodEndAfter(
  start: IsoTimestamp,
  interval: BillingInterval,
): IsoTimestamp {
  const end = parseIso(start);
  const day = end.getUTCDate();

  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + monthsIn(interval));

  const lastDay = new Date(
    Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, 0),
  ).getUTCDate();
  end.setUTCDate(Math.min(day, lastDay));

  return toIsoTimestamp(end);
}

/**
 * The consecutive periods that begin at `from` and keep going while the next
 * one has already begun by `now`. The last period returned is the one that
 * covers `now`, so a subscription that is several periods behind comes back
 * with one entry per elapsed interval. Empty when `from` is still in the
 * future.
 */
export function periodsElapsedBy(
  from: IsoTimestamp,
  interval: BillingInterval,
  now: Date,
): readonly BillingPeriod[] {
  const periods: BillingPeriod[] = [];

  let start = from;
  while (parseIso(start).getTime() <= now.getTime()) {
    const end = periodEndAfter(start, interval);
    periods.push({ start, end });
    start = end;
  }

  return periods;
}

/** Whole days in a period, rounded and never below one. */
export function daysInPeriod(period: BillingPeriod): number {
  const span =
    parseIso(period.end).getTime() - parseIso(period.start).getTime();
  return Math.max(1, Math.round(span / MS_PER_DAY));
}

/**
 * Whole or started days from `now` to the period end, so 14 days and 22 hours
 * left count as 15. Zero once the end has been reached.
 */
export function daysLeft(period: BillingPeriod, now: Date): number {
  const remainingMs = parseIso(period.end).getTime() - now.getTime();
  return remainingMs <= 0 ? 0 : Math.ceil(remainingMs / MS_PER_DAY);
}

/**
 * The share of `fullCents` still owed for the rest of `period` from `now`,
 * rounded down to whole cents.
 */
export function prorate(
  fullCents: number,
  period: BillingPeriod,
  now: Date,
): number {
  return Math.floor((fullCents * daysLeft(period, now)) / daysInPeriod(period));
}

/**
 * The full charge for one interval on `plan`: the monthly price per seat ×
 * seats × the months the interval spans, in cents.
 */
export function fullPeriodCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval)
  );
}

