/**
 * Subscription rows; one active row per organization.
 */
import { and, asc, count, eq, gt, inArray, isNotNull, isNull, lte, ne } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invoices, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvoice, toSubscription } from "./_mappers";
import type {
  BillingInterval,
  Invoice,
  PlanId,
  Subscription,
  SubscriptionStatus,
} from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

/** The fields a billing change may write; anything left out is untouched. */
export interface SubscriptionChange {
  readonly plan?: PlanId;
  readonly interval?: BillingInterval;
  readonly status?: SubscriptionStatus;
  readonly seats?: number;
  readonly currentPeriodStart?: IsoTimestamp;
  readonly currentPeriodEnd?: IsoTimestamp;
  readonly cancelAt?: IsoTimestamp | null;
}

/** An invoice the caller has priced; the repository numbers and stores it. */
export interface InvoiceDraft {
  readonly amountCents: number;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
}

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = toIsoTimestamp(
    new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status: "active", updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

export async function updateSeatCount(
  orgId: OrgId,
  seats: number,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * Writes a subscription change and the invoices it produces in one
 * transaction: a billed period is never invoiced without the subscription
 * moving past it, nor moved past without being invoiced.
 */
export async function commitSubscriptionChange(
  orgId: OrgId,
  change: SubscriptionChange,
  drafts: readonly InvoiceDraft[],
): Promise<{ subscription: Subscription; invoices: readonly Invoice[] }> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ ...change, updatedAt: stamp })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Subscription for org ${orgId} not found`);

    const issued = drafts.map((draft) => {
      // Counted inside the transaction so each draft sees the one before it.
      const existing = tx
        .select({ value: count() })
        .from(invoices)
        .where(orgPredicate(invoices.orgId, orgId))
        .get();

      return tx
        .insert(invoices)
        .values({
          id: newId(),
          orgId,
          number: invoiceNumber((existing?.value ?? 0) + 1),
          amountCents: draft.amountCents,
          currency: "usd",
          periodStart: draft.periodStart,
          periodEnd: draft.periodEnd,
          paidAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
    });

    return {
      subscription: toSubscription(row),
      invoices: issued.map(toInvoice),
    };
  });
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}

/**
 * Feeds the billing renewal job: one page of the subscriptions that can still
 * move (active or canceled) in workspaces that have not been archived, in id
 * order after `afterId`. Cross-tenant by design, like the trial sweep. Paging
 * by id rather than taking a single batch means the job reaches every
 * workspace however many there are.
 */
export async function listSubscriptionsForRenewal(
  afterId: string | null,
  limit: number,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        inArray(subscriptions.status, ["active", "canceled"]),
        isNull(organizations.archivedAt),
        afterId === null ? undefined : gt(subscriptions.id, afterId),
      ),
    )
    .orderBy(asc(subscriptions.id))
    .limit(limit)
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/** INV-000001, INV-000002 … — unique within the workspace by construction. */
function invoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(6, "0")}`;
}

