/**
 * Plan changes, seat changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, getLimit, wouldExceedLimit, fullPeriodCents, periodEndAfter, prorate
 */
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import {
  fullPeriodCents,
  monthsIn,
  periodEndAfter,
  prorate,
} from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  InvoiceDraft,
  SubscriptionChange,
} from "@/server/repositories/subscription-repository";
import type {
  BillingInterval,
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

/** What a plan change writes to the subscription, and the invoices it owes. */
interface PlannedChange {
  readonly change: SubscriptionChange;
  readonly drafts: readonly InvoiceDraft[];
}

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents: fullPeriodCents(
      subscription.plan,
      subscription.seats,
      subscription.interval,
    ),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const planned = planChange(subscription, input.plan, input.interval, new Date());
  const committed = await subscriptionRepo.commitSubscriptionChange(
    input.orgId,
    planned.change,
    planned.drafts,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });
  await announceInvoices(input.orgId, committed.invoices);

  return committed.subscription;
}

/**
 * Seats added mid-period are billed for the rest of the period; seats removed
 * are neither charged nor credited. Only an active subscription on a paid plan
 * is billed.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  if (input.seats > getLimit(subscription.plan, "seats")) {
    throw new Error(
      `Plan ${subscription.plan} tops out at ${getLimit(subscription.plan, "seats")} seats`,
    );
  }

  const now = new Date();
  const added = Math.max(0, input.seats - subscription.seats);
  const drafts = isBilled(subscription)
    ? proratedDrafts(
        subscription,
        fullPeriodCents(subscription.plan, added, subscription.interval),
        now,
      )
    : [];

  const committed = await subscriptionRepo.commitSubscriptionChange(
    input.orgId,
    { seats: input.seats },
    drafts,
  );
  await announceInvoices(input.orgId, committed.invoices);

  return committed.subscription;
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * Publishes one `billing.invoice_issued` per invoice; the audit log and the
 * owner's notification both hang off it. No actor is recorded: the invoice
 * belongs to the workspace, and the owner is told of it even when their own
 * seat change is what triggered it.
 */
export async function announceInvoices(
  orgId: OrgId,
  invoices: readonly Invoice[],
): Promise<void> {
  for (const invoice of invoices) {
    await emit("billing.invoice_issued", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      invoiceId: invoice.id,
      invoiceNumber: invoice.number,
      amountCents: invoice.amountCents,
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
    });
  }
}

/**
 * What a plan change writes, and what it bills. A trial keeps its period and
 * bills nothing (its first invoice comes at renewal). Leaving the free plan
 * opens a fresh period, billed in full. Between two paid plans, an upgrade is
 * billed for the rest of the period that is in progress; a downgrade or an
 * unchanged plan is not billed at all.
 */
function planChange(
  subscription: Subscription,
  plan: PlanId,
  interval: BillingInterval,
  now: Date,
): PlannedChange {
  const change: SubscriptionChange = { plan, interval, status: "active" };
  if (subscription.status !== "active") return { change, drafts: [] };

  const current = subscription.plan;

  if (current === "free" && plan !== "free") {
    const start = toIsoTimestamp(now);
    const end = periodEndAfter(start, interval);
    return {
      change: { ...change, currentPeriodStart: start, currentPeriodEnd: end },
      drafts: [
        {
          amountCents: fullPeriodCents(plan, subscription.seats, interval),
          periodStart: start,
          periodEnd: end,
        },
      ],
    };
  }

  if (current !== "free" && plan !== "free") {
    const perSeatIncrease = Math.max(
      0,
      getPlanLimits(plan).priceCentsPerSeatMonthly -
        getPlanLimits(current).priceCentsPerSeatMonthly,
    );
    // The period in progress is not changed, so it is priced in the months
    // of the interval it was started under.
    const fullCents =
      perSeatIncrease * subscription.seats * monthsIn(subscription.interval);

    return { change, drafts: proratedDrafts(subscription, fullCents, now) };
  }

  return { change, drafts: [] };
}

/** Only an active subscription on a paid plan is billed for mid-period changes. */
function isBilled(subscription: Subscription): boolean {
  return subscription.status === "active" && subscription.plan !== "free";
}

/**
 * The invoice for `fullCents` prorated over the rest of the current period, or
 * none when nothing is owed. The period itself is not changed.
 */
function proratedDrafts(
  subscription: Subscription,
  fullCents: number,
  now: Date,
): readonly InvoiceDraft[] {
  const period = {
    start: subscription.currentPeriodStart,
    end: subscription.currentPeriodEnd,
  };
  const amountCents = prorate(fullCents, period, now);

  return amountCents > 0
    ? [{ amountCents, periodStart: period.start, periodEnd: period.end }]
    : [];
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}

