  const planned = planChange(subscription, input.plan, input.interval, new Date());
  const committed = await subscriptionRepo.commitSubscriptionChange(
    input.orgId,
    planned.change,
    planned.drafts,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });
