 * owner's notification both hang off it. No actor is recorded: the invoice
 * belongs to the workspace, and the owner is told of it even when their own
 * seat change is what triggered it.
 */
export async function announceInvoices(
  orgId: OrgId,
  invoices: readonly Invoice[],
): Promise<void> {
  for (const invoice of invoices) {
    await emit("billing.invoice_issued", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      invoiceId: invoice.id,
      invoiceNumber: invoice.number,
      amountCents: invoice.amountCents,
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
    });
  }
}

/**
 * What a plan change writes, and what it bills. A trial keeps its period and
 * bills nothing (its first invoice comes at renewal). Leaving the free plan
 * opens a fresh period, billed in full. Between two paid plans, an upgrade is
 * billed for the rest of the period that is in progress; a downgrade or an
 * unchanged plan is not billed at all.
 */
function planChange(
  subscription: Subscription,
  plan: PlanId,
  interval: BillingInterval,
  now: Date,
): PlannedChange {
  const change: SubscriptionChange = { plan, interval, status: "active" };
  if (subscription.status !== "active") return { change, drafts: [] };

  const current = subscription.plan;

  if (current === "free" && plan !== "free") {
    const start = toIsoTimestamp(now);
    const end = periodEndAfter(start, interval);
    return {
      change: { ...change, currentPeriodStart: start, currentPeriodEnd: end },
      drafts: [
        {
          amountCents: fullPeriodCents(plan, subscription.seats, interval),
          periodStart: start,
          periodEnd: end,
        },
      ],
    };
  }

  if (current !== "free" && plan !== "free") {
    const perSeatIncrease = Math.max(
      0,
      getPlanLimits(plan).priceCentsPerSeatMonthly -
        getPlanLimits(current).priceCentsPerSeatMonthly,
    );
    // The period in progress is not changed, so it is priced in the months
    // of the interval it was started under.
    const fullCents =
      perSeatIncrease * subscription.seats * monthsIn(subscription.interval);

    return { change, drafts: proratedDrafts(subscription, fullCents, now) };
  }

  return { change, drafts: [] };
}

/** Only an active subscription on a paid plan is billed for mid-period changes. */
function isBilled(subscription: Subscription): boolean {
  return subscription.status === "active" && subscription.plan !== "free";
}

/**
 * The invoice for `fullCents` prorated over the rest of the current period, or
 * none when nothing is owed. The period itself is not changed.
 */
function proratedDrafts(
  subscription: Subscription,
  fullCents: number,
  now: Date,
): readonly InvoiceDraft[] {
  const period = {
    start: subscription.currentPeriodStart,
    end: subscription.currentPeriodEnd,
  };
  const amountCents = prorate(fullCents, period, now);

  return amountCents > 0
    ? [{ amountCents, periodStart: period.start, periodEnd: period.end }]
    : [];
}

