/**
 * Moves subscriptions along their billing periods. An active one whose period has ended is renewed period by period, every paid period invoiced in full; a canceled one ends on its cancellation date and drops to the free plan.
 *
 * Must call (do not reimplement): emit, fullPeriodCents, periodsElapsedBy, commitSubscriptionChange, announceInvoices
 */
import { fullPeriodCents, periodsElapsedBy } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { announceInvoices } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { BillingPeriod } from "@/lib/billing-period";
import type { InvoiceDraft } from "@/server/repositories/subscription-repository";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

/** Subscriptions read per page; paging by id means no workspace is skipped. */
const PAGE_SIZE = 100;

/** Where a canceled subscription lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * Runs once an hour. Idempotent: a subscription is only touched when a period
 * has ended or a cancellation date has passed, and every change moves that
 * boundary past `now`, so a second run at the same instant finds nothing to do.
 *
 * A failing subscription is counted and logged, and the pass carries on with
 * the rest.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;
    let page: readonly Subscription[];

    do {
      page = await subscriptionRepo.listSubscriptionsForRenewal(afterId, PAGE_SIZE);

      for (const subscription of page) {
        try {
          if (await settle(subscription, now)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      afterId = page.at(-1)?.id ?? afterId;
    } while (page.length === PAGE_SIZE);
  });
}

/** Returns whether the subscription's stored state changed. */
async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  if (subscription.status === "canceled") return endCanceled(subscription, now);
  return renew(subscription, now);
}

/**
 * Appends one period per elapsed interval and invoices each one when the plan
 * is paid. The seat count used is the one held at this moment.
 */
async function renew(subscription: Subscription, now: Date): Promise<boolean> {
  const periods = periodsElapsedBy(
    subscription.currentPeriodEnd,
    subscription.interval,
    now,
  );
  const first = periods[0];
  const last = periods.at(-1);
  if (first === undefined || last === undefined) return false;

  const billed = subscription.plan !== FALLBACK_PLAN;
  const amountCents = fullPeriodCents(
    subscription.plan,
    subscription.seats,
    subscription.interval,
  );
  const drafts: readonly InvoiceDraft[] = billed
    ? periods.map((period) => invoiceFor(period, amountCents))
    : [];

  const committed = await subscriptionRepo.commitSubscriptionChange(
    subscription.orgId,
    { currentPeriodStart: first.start, currentPeriodEnd: last.end },
    drafts,
  );
  await announceInvoices(subscription.orgId, committed.invoices);

  return true;
}

/**
 * Ends a canceled subscription on its cancellation date: the workspace moves
 * to the free plan with a monthly period starting that day. Free periods run
 * on like any other, so the period is rolled forward to cover `now`, but
 * nothing is invoiced.
 */
async function endCanceled(subscription: Subscription, now: Date): Promise<boolean> {
  const cancelAt = subscription.cancelAt;
  if (cancelAt === null || parseIso(cancelAt).getTime() > now.getTime()) {
    return false;
  }

  const periods = periodsElapsedBy(cancelAt, "monthly", now);
  const first = periods[0];
  const last = periods.at(-1);
  if (first === undefined || last === undefined) return false;

  await subscriptionRepo.commitSubscriptionChange(
    subscription.orgId,
    {
      plan: FALLBACK_PLAN,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: first.start,
      currentPeriodEnd: last.end,
    },
    [],
  );

  if (subscription.plan !== FALLBACK_PLAN) {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: FALLBACK_PLAN,
    });
  }

  return true;
}

function invoiceFor(period: BillingPeriod, amountCents: number): InvoiceDraft {
  return { amountCents, periodStart: period.start, periodEnd: period.end };
}

