/**
 * Period boundaries, day counts and proration for billing.
 */
import { describe, expect, it } from "vitest";
import {
  daysInPeriod,
  daysLeft,
  fullPeriodCents,
  periodEndAfter,
  periodsElapsedBy,
  prorate,
} from "@/lib/billing-period";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

const at = (value: string): IsoTimestamp => toIsoTimestamp(new Date(value));

describe("lib/billing-period: period ends", () => {
  it("ends a monthly period on the same day of the next month", () => {
    expect(periodEndAfter(at("2026-03-10T09:30:00.000Z"), "monthly")).toBe(
      "2026-04-10T09:30:00.000Z",
    );
  });

  it("clamps to the last day when the next month is shorter", () => {
    expect(periodEndAfter(at("2026-01-31T00:00:00.000Z"), "monthly")).toBe(
      "2026-02-28T00:00:00.000Z",
    );
    expect(periodEndAfter(at("2028-01-31T00:00:00.000Z"), "monthly")).toBe(
      "2028-02-29T00:00:00.000Z",
    );
  });

  it("carries a clamped day forward into the next period", () => {
    const first = periodEndAfter(at("2026-01-31T00:00:00.000Z"), "monthly");
    expect(first).toBe("2026-02-28T00:00:00.000Z");
    expect(periodEndAfter(first, "monthly")).toBe("2026-03-28T00:00:00.000Z");
  });

  it("ends an annual period on the same day and month of the next year", () => {
    expect(periodEndAfter(at("2026-06-15T12:00:00.000Z"), "annual")).toBe(
      "2027-06-15T12:00:00.000Z",
    );
  });

  it("ends an annual period started on 29 February on 28 February", () => {
    expect(periodEndAfter(at("2028-02-29T00:00:00.000Z"), "annual")).toBe(
      "2029-02-28T00:00:00.000Z",
    );
  });
});

describe("lib/billing-period: periods elapsed", () => {
  it("returns nothing while the period has not yet ended", () => {
    const periods = periodsElapsedBy(
      at("2026-06-01T00:00:00.000Z"),
      "monthly",
      new Date("2026-05-31T23:00:00.000Z"),
    );
    expect(periods).toEqual([]);
  });

  it("returns one period per elapsed interval, ending with the one covering now", () => {
    const periods = periodsElapsedBy(
      at("2026-02-15T00:00:00.000Z"),
      "monthly",
      new Date("2026-05-20T07:00:00.000Z"),
    );

    expect(periods.map((period) => [period.start, period.end])).toEqual([
      ["2026-02-15T00:00:00.000Z", "2026-03-15T00:00:00.000Z"],
      ["2026-03-15T00:00:00.000Z", "2026-04-15T00:00:00.000Z"],
      ["2026-04-15T00:00:00.000Z", "2026-05-15T00:00:00.000Z"],
      ["2026-05-15T00:00:00.000Z", "2026-06-15T00:00:00.000Z"],
    ]);
  });
});

describe("lib/billing-period: days and proration", () => {
  it("counts the whole days in a monthly and an annual period", () => {
    expect(
      daysInPeriod({
        start: at("2026-02-01T00:00:00.000Z"),
        end: at("2026-03-01T00:00:00.000Z"),
      }),
    ).toBe(28);
    expect(
      daysInPeriod({
        start: at("2026-01-01T00:00:00.000Z"),
        end: at("2027-01-01T00:00:00.000Z"),
      }),
    ).toBe(365);
  });

  it("counts a started day as a whole day left", () => {
    const period = {
      start: at("2026-06-01T00:00:00.000Z"),
      end: at("2026-06-16T00:00:00.000Z"),
    };
    // 14 days and 22 hours left.
    expect(daysLeft(period, new Date("2026-06-01T02:00:00.000Z"))).toBe(15);
  });

  it("has no days left once the period end has been reached", () => {
    const period = {
      start: at("2026-06-01T00:00:00.000Z"),
      end: at("2026-07-01T00:00:00.000Z"),
    };
    expect(daysLeft(period, new Date("2026-07-01T00:00:00.000Z"))).toBe(0);
    expect(daysLeft(period, new Date("2026-08-01T00:00:00.000Z"))).toBe(0);
  });

  it("prorates by days left over days in the period, rounding down to cents", () => {
    const period = {
      start: at("2026-06-01T00:00:00.000Z"),
      end: at("2026-07-01T00:00:00.000Z"),
    };
    // 15 of 30 days left.
    expect(prorate(9_000, period, new Date("2026-06-16T00:00:00.000Z"))).toBe(4_500);
    // 10 of 31 days left: 1000 * 10 / 31 = 322.58…
    const july = {
      start: at("2026-07-01T00:00:00.000Z"),
      end: at("2026-08-01T00:00:00.000Z"),
    };
    expect(prorate(1_000, july, new Date("2026-07-22T00:00:00.000Z"))).toBe(322);
  });

  it("prices a full period as the monthly seat price × seats × months", () => {
    expect(fullPeriodCents("growth", 5, "monthly")).toBe(9_500);
    expect(fullPeriodCents("growth", 5, "annual")).toBe(114_000);
    expect(fullPeriodCents("free", 5, "annual")).toBe(0);
  });
});

