    const first = periodEndAfter(at("2026-01-31T00:00:00.000Z"), "monthly");
    expect(first).toBe("2026-02-28T00:00:00.000Z");
    expect(periodEndAfter(first, "monthly")).toBe("2026-03-28T00:00:00.000Z");
  });

  it("ends an annual period on the same day and month of the next year", () => {
    expect(periodEndAfter(at("2026-06-15T12:00:00.000Z"), "annual")).toBe(
      "2027-06-15T12:00:00.000Z",
    );
  });

  it("ends an annual period started on 29 February on 28 February", () => {
    expect(periodEndAfter(at("2028-02-29T00:00:00.000Z"), "annual")).toBe(
      "2029-02-28T00:00:00.000Z",
