 * has ended or a cancellation date has passed, and every change moves that
 * boundary past `now`, so a second run at the same instant finds nothing to do.
 *
 * A failing subscription is counted and logged, and the pass carries on with
 * the rest.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;
    let page: readonly Subscription[];

    do {
      page = await subscriptionRepo.listSubscriptionsForRenewal(afterId, PAGE_SIZE);

      for (const subscription of page) {
        try {
          if (await settle(subscription, now)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      afterId = page.at(-1)?.id ?? afterId;
    } while (page.length === PAGE_SIZE);
  });
}

