/**
 * The billing renewal job: ended periods are renewed and invoiced, cancellations
 * take effect on their date, and a second pass at the same instant changes nothing.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
// Attaches the notification fan-out at import; nothing else exposes it.
import "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

const NOW = new Date("2026-05-20T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** Collects every payload delivered for one event type during a test. */
function capture<K extends "billing.invoice_issued" | "billing.plan_changed">(
  type: K,
): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Writes subscription state directly, so each case starts exactly where it says. */
function schedule(
  orgId: OrgId,
  patch: Partial<typeof subscriptions.$inferInsert>,
): void {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

/** A growth workspace, active, with five seats, whose period ended on 15 February. */
async function behindOnGrowth(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug, "growth");
  schedule(tenant.org.id, {
    status: "active",
    interval: "monthly",
    seats: 5,
    currentPeriodStart: "2026-01-15T00:00:00.000Z",
    currentPeriodEnd: "2026-02-15T00:00:00.000Z",
  });
  return tenant;
}

describe("billing renewal: active subscriptions", () => {
  it("renews once per elapsed period and invoices each paid period in full", async () => {
    const tenant = await behindOnGrowth("renew-paid");

    const result = await runBillingRenewalJob(NOW);
    expect(result.failed).toBe(0);

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub).toMatchObject({
      plan: "growth",
      status: "active",
      currentPeriodStart: "2026-05-15T00:00:00.000Z",
      currentPeriodEnd: "2026-06-15T00:00:00.000Z",
    });

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-05-15T00:00:00.000Z",
      "2026-04-15T00:00:00.000Z",
      "2026-03-15T00:00:00.000Z",
      "2026-02-15T00:00:00.000Z",
    ]);
    expect(invoices.map((invoice) => invoice.periodEnd)).toEqual([
      "2026-06-15T00:00:00.000Z",
      "2026-05-15T00:00:00.000Z",
      "2026-04-15T00:00:00.000Z",
      "2026-03-15T00:00:00.000Z",
    ]);
    for (const invoice of invoices) {
      expect(invoice.amountCents).toBe(9_500);
      expect(invoice.currency).toBe("usd");
      expect(invoice.paidAt).toBeNull();
    }
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(4);
  });

  it("changes nothing on a second run at the same instant", async () => {
    const tenant = await behindOnGrowth("renew-replay");
    await runBillingRenewalJob(NOW);

    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    const invoicesBefore = await invoiceRepo.listInvoices(tenant.org.id);
    const announced = capture("billing.invoice_issued");

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual(invoicesBefore);
    expect(announced.filter((event) => event.orgId === tenant.org.id)).toEqual([]);
  });

  it("publishes, audits and tells the owner about each invoice, and nobody else", async () => {
    const tenant = await behindOnGrowth("renew-announce");
    const announced = capture("billing.invoice_issued");

    await runBillingRenewalJob(NOW);

    const events = announced.filter((event) => event.orgId === tenant.org.id);
    expect(events).toHaveLength(4);
    expect(events[0]).toMatchObject({
      actorId: null,
      amountCents: 9_500,
      periodStart: "2026-05-15T00:00:00.000Z",
      periodEnd: "2026-06-15T00:00:00.000Z",
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 50,
      cursor: null,
    });
    expect(audit.total).toBe(4);
    expect(audit.items[0]).toMatchObject({
      action: "billing.invoice_issued",
      subjectKind: "subscription",
      subjectId: tenant.org.id,
    });

    const owner = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["invoice_issued"],
      limit: 50,
      cursor: null,
    });
    expect(owner.total).toBe(4);

    const admin = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["invoice_issued"],
      limit: 50,
      cursor: null,
    });
    expect(admin.total).toBe(0);
  });

  it("moves a free workspace's period on without invoicing it", async () => {
    const tenant = await createTenant("renew-free", "free");
    schedule(tenant.org.id, {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub).toMatchObject({
      plan: "free",
      status: "active",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("leaves a period that has not ended alone", async () => {
    const tenant = await createTenant("renew-not-due", "growth");
    schedule(tenant.org.id, {
      status: "active",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("reaches every workspace, not only the first page", async () => {
    const owner = await userRepo.insertUser({
      email: "bulk-owner@renew.test",
      name: "Bulk owner",
      passwordHash: "seed",
    });

    const orgIds: OrgId[] = [];
    for (let index = 0; index < 105; index += 1) {
      const org = await orgRepo.insertOrg(
        { name: `Bulk ${index}`, slug: `bulk-${index}`, plan: "growth" },
        owner.id,
      );
      await subscriptionRepo.insertSubscription(org.id, "growth", "monthly");
      schedule(org.id, {
        status: "active",
        currentPeriodStart: "2026-04-01T00:00:00.000Z",
        currentPeriodEnd: "2026-05-01T00:00:00.000Z",
      });
      orgIds.push(org.id);
    }

    const result = await runBillingRenewalJob(NOW);
    expect(result.failed).toBe(0);

    for (const orgId of orgIds) {
      expect(await subscriptionRepo.findSubscription(orgId)).toMatchObject({
        currentPeriodEnd: "2026-06-01T00:00:00.000Z",
      });
    }
  });
});

describe("billing renewal: cancellations", () => {
  it("ends a canceled subscription on its cancellation date, without an invoice", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    schedule(tenant.org.id, {
      status: "canceled",
      interval: "annual",
      seats: 5,
      cancelAt: "2026-05-01T00:00:00.000Z",
