  });

  it("leaves a canceled subscription alone until its cancellation date", async () => {
    const tenant = await createTenant("renew-cancel-later", "growth");
    schedule(tenant.org.id, {
      status: "canceled",
      seats: 5,
      cancelAt: "2026-07-01T00:00:00.000Z",
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
