/**
 * Mid-period charges for seat changes and plan changes.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Fifteen of the thirty days in June are left at this instant. */
const MID_JUNE = new Date("2026-06-16T00:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(MID_JUNE);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

function capture(type: "billing.invoice_issued"): TaskflowEventMap[typeof type][] {
  const seen: TaskflowEventMap[typeof type][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function schedule(
  orgId: OrgId,
  patch: Partial<typeof subscriptions.$inferInsert>,
): void {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

/** A growth workspace, active, monthly, on the June period. */
async function activeGrowth(slug: string, seats = 5): Promise<Tenant> {
  const tenant = await createTenant(slug, "growth");
  schedule(tenant.org.id, {
    status: "active",
    interval: "monthly",
    seats,
    currentPeriodStart: "2026-06-01T00:00:00.000Z",
    currentPeriodEnd: "2026-07-01T00:00:00.000Z",
  });
  return tenant;
}

describe("seat changes", () => {
  it("bills seats added mid-period for the rest of the period", async () => {
    const tenant = await activeGrowth("prorate-seats-up");
    const announced = capture("billing.invoice_issued");

    const updated = await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 7,
    });

    expect(updated.seats).toBe(7);
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 1_900,
      periodStart: "2026-06-01T00:00:00.000Z",
      periodEnd: "2026-07-01T00:00:00.000Z",
    });
    expect(announced.filter((event) => event.orgId === tenant.org.id)).toEqual([
      expect.objectContaining({ actorId: null, amountCents: 1_900 }),
    ]);
  });

  it("neither charges nor credits seats removed", async () => {
    const tenant = await activeGrowth("prorate-seats-down");

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 3,
    });

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("charges nothing for seats during a trial", async () => {
    const tenant = await createTenant("prorate-trial-seats", "growth");
    schedule(tenant.org.id, {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 6,
    });

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("charges nothing for seats on the free plan", async () => {
    const tenant = await createTenant("prorate-free-seats", "free");
    schedule(tenant.org.id, {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 3,
    });

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });
});

describe("plan changes", () => {
  it("charges the price difference for the rest of the period on an upgrade", async () => {
    const tenant = await activeGrowth("prorate-upgrade");
    schedule(tenant.org.id, { plan: "starter" });

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(updated).toMatchObject({
      plan: "growth",
      status: "active",
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });
    // (1900 - 900) × 5 seats × 1 month, of which 15 of 30 days remain.
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([2_500]);
    expect(invoices[0]).toMatchObject({
      periodStart: "2026-06-01T00:00:00.000Z",
      periodEnd: "2026-07-01T00:00:00.000Z",
    });
  });

  it("charges nothing for a downgrade, and leaves the period alone", async () => {
    const tenant = await activeGrowth("prorate-downgrade");

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    expect(updated).toMatchObject({
      plan: "starter",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("keeps the trial period when a plan is chosen during a trial", async () => {
    const tenant = await createTenant("prorate-trial-choice", "growth");
    schedule(tenant.org.id, {
      currentPeriodStart: "2026-06-10T00:00:00.000Z",
      currentPeriodEnd: "2026-06-24T00:00:00.000Z",
    });

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "annual",
    });

    expect(updated).toMatchObject({
      plan: "enterprise",
      interval: "annual",
      status: "active",
      currentPeriodStart: "2026-06-10T00:00:00.000Z",
      currentPeriodEnd: "2026-06-24T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("starts a fresh period and bills it in full when leaving the free plan", async () => {
    const tenant = await createTenant("prorate-first-paid", "free");
    schedule(tenant.org.id, { seats: 5 });

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });

    expect(updated).toMatchObject({
      plan: "growth",
      interval: "annual",
      currentPeriodStart: "2026-06-16T00:00:00.000Z",
      currentPeriodEnd: "2027-06-16T00:00:00.000Z",
    });
    // 1900 × 5 seats × 12 months.
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
