      interval: "annual",
      currentPeriodStart: "2026-06-16T00:00:00.000Z",
      currentPeriodEnd: "2027-06-16T00:00:00.000Z",
    });
    // 1900 × 5 seats × 12 months.
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 114_000,
      periodStart: "2026-06-16T00:00:00.000Z",
      periodEnd: "2027-06-16T00:00:00.000Z",
