99	/**
100	 * Ends a canceled subscription on its cancellation date: the workspace moves
101	 * to the free plan with a monthly period starting that day. Free periods run
102	 * on like any other, so the period is rolled forward to cover `now`, but
103	 * nothing is invoiced.
104	 */
105	async function endCanceled(subscription: Subscription, now: Date): Promise<boolean> {
106	  const cancelAt = subscription.cancelAt;
107	  if (cancelAt === null || parseIso(cancelAt).getTime() > now.getTime()) {
108	    return false;
109	  }
110	
111	  const last = periodsElapsedBy(cancelAt, "monthly", now).at(-1);
112	  if (last === undefined) return false;
113	
114	  await subscriptionRepo.commitSubscriptionChange(
115	    subscription.orgId,
116	    {
117	      plan: FALLBACK_PLAN,
118	      interval: "monthly",
119	      status: "active",
120	      cancelAt: null,
121	      currentPeriodStart: last.start,
122	      currentPeriodEnd: last.end,
123	    },
124	    [],
125	  );
126	
127	  if (subscription.plan !== FALLBACK_PLAN) {
128	    await emit("billing.plan_changed", {
129	      orgId: subscription.orgId,
130	      actorId: null,
131	      occurredAt: toIsoTimestamp(now),
132	      from: subscription.plan,
133	      to: FALLBACK_PLAN,
134	    });

