/** Returns whether the subscription's stored state changed. */
async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  if (subscription.status === "canceled") return endCanceled(subscription, now);
  return renew(subscription, now);
}

/**
 * Appends one period per elapsed interval and invoices each one when the plan
 * is paid. The seat count used is the one held at this moment.
 */
async function renew(subscription: Subscription, now: Date): Promise<boolean> {
  const periods = periodsElapsedBy(
    subscription.currentPeriodEnd,
    subscription.interval,
    now,
  );
  const last = periods.at(-1);
  if (last === undefined) return false;

  const billed = subscription.plan !== FALLBACK_PLAN;
  const amountCents = fullPeriodCents(
    subscription.plan,
    subscription.seats,
    subscription.interval,
  );
  const drafts: readonly InvoiceDraft[] = billed
    ? periods.map((period) => invoiceFor(period, amountCents))
    : [];

  const committed = await subscriptionRepo.commitSubscriptionChange(
    subscription.orgId,
    { currentPeriodStart: last.start, currentPeriodEnd: last.end },
    drafts,
  );
  await announceInvoices(subscription.orgId, committed.invoices);

  return true;
}

/**
 * Ends a canceled subscription on its cancellation date: the workspace moves
 * to the free plan with a monthly period starting that day. Free periods run
 * on like any other, so the period is rolled forward to cover `now`, but
 * nothing is invoiced.
 */
async function endCanceled(subscription: Subscription, now: Date): Promise<boolean> {
  const cancelAt = subscription.cancelAt;
  if (cancelAt === null || parseIso(cancelAt).getTime() > now.getTime()) {
    return false;
  }

  const last = periodsElapsedBy(cancelAt, "monthly", now).at(-1);
  if (last === undefined) return false;

  await subscriptionRepo.commitSubscriptionChange(
    subscription.orgId,
    {
      plan: FALLBACK_PLAN,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: last.start,
      currentPeriodEnd: last.end,
    },
    [],
  );

  if (subscription.plan !== FALLBACK_PLAN) {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: FALLBACK_PLAN,
    });

